SELECT e.run_id, e.run_ts, e.analysis_date, e.universe_size, e.stocks_analyzed, e.stocks_filtered, e.indices_analyzed, e.market_composite_score, e.market_sentiment
FROM report.enhanced_runs e
WHERE e.run_ts >= CURRENT_DATE - INTERVAL '1 week';

SELECT f.run_id, f.symbol, f.score, f.recommendation, f.current_price, f.weekly_signal, f.daily_signal, f.rsi, f.tech_score, f.fund_score
FROM report.enhanced_filtered_stocks f, report.enhanced_runs e
WHERE f.run_id = e.run_id AND e.run_ts >= CURRENT_DATE - INTERVAL '1 week';

